window.KEPCO_POPUP_BUNDLE = Object.assign(window.KEPCO_POPUP_BUNDLE || {}, {
"popups/SRMContractDocumentManage/screenDescriptionGuide.html": "<!-- 자동 생성 파일: 직접 수정하지 말고 docs/DESCRIPTION_MAP.json 수정 후 python3 tools/build_description_guides.py 실행 -->\n<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection1\">\n          <h3 id=\"descriptionSection1\">계약 관련 서류(등록된 ‘계약 관련 서류’ 조회 및 확정 처리)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 11</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-11:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">현재 해당 건에 등록된 ‘계약 관련 서류’ 현황을 보여줌</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection2\">\n          <h3 id=\"descriptionSection2\">계약 관련 서류(등록된 ‘계약 관련 서류’ 조회 및 확정 처리)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 12</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-12:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘확정 처리(계약정보로 전송)’ 클릭 시  계약정보와 PMS의 계약정보에 업데이트(덮어쓰기) 함\n\n진행상태를 ‘계약완료’로 변경\n\n확정된 항목은 협력업체가 더 이상 수정할 수 없음\n\n‘확정(수정 불가)’의 체크를 제거하고 ‘확정 처리(계약정보로 전송)’ 클릭 시 협력업체는 다시 파일을 등록할 수 있음\n\n이 기능이 있는 이유는 협력업체가 등록해야 하는 파일(계약이행/선금이행/하자이행 보증보험 증권)이 한 번에 등록되지 않고 사업기간 중에 순차적으로 등록되기 때문임</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-12:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">관리자는 ‘등록/수정’ 기능을 통해 계약 관련 서류를 상시 등록/수정할 수 있음</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection3\">\n          <h3 id=\"descriptionSection3\">계약 관련 서류(서류 등록/수정)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 13</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-13:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">입찰관리에서 본 ‘발주계약 현황’으로 넘어올 때 입력되었던 정보를 보여줌.\n(수정 가능)\n\n협력업체가 각종 증권(계약이행 보증보험 증권, 선금이행 보증보험 증권, 하자이행 보증보험 증권)을 발급하기 위해서는 계약서(날인본)이 필요함\n\n켑코이에스가 먼저 계약서 날인본을 제공해야 함</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-13:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">협력업체가 등록해야 하는 서류를 관리자가 직접 등록해 줄 수도 있음.</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMContractStatus/ctChangeConfirmModal.html": "<div class=\"modal-backdrop\" id=\"ctChangeConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"ctChangeConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"ctChangeConfirmTitle\">변경 계약 처리 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead\">변경 계약 처리(PMS로 계약정보 전송) 시 PMS로 계약정보가 전송/업데이트됩니다. 변경 계약 관련 서류를 다시 한 번 면밀히 확인하세요.</p><p>변경 계약(PMS로 계약정보 전송) 처리하시겠습니까?</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" data-description-ref=\"08-9:4’\" aria-hidden=\"true\"></span><button type=\"button\" class=\"btn-critical-primary\" data-close-modal>변경 계약 처리(PMS로 계약정보 전송)</button></span><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMContractStatus/ctChangeDetailModal.html": "<div class=\"modal-backdrop\" id=\"ctChangeDetailModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ctChangeDetailTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"ctChangeDetailTitle\">계약 변경 내역 상세보기</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row\"><dt>계약변경일</dt><dd>2026.09.01</dd></div>\n          <div class=\"srm-kv-row description-marker-container\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-10:1\" aria-hidden=\"true\"></span><dt>변경계약 사유</dt><dd data-ui-value=\"amount\" data-ui-source=\"change\">'계약금액' 변경</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-10:2\" aria-hidden=\"true\"></span><dt>기존 계약금액</dt><dd>99,000,000원 (구천구백만원, VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-10:2’\" aria-hidden=\"true\"></span><dt>변경된 계약금액</dt><dd>92,000,000원 (구천이백만원, VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-10:3\" aria-hidden=\"true\"></span><dt>기존 납기일/공사기간</dt><dd>2026.07.20 ~ 2027.07.30</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-10:3’\" aria-hidden=\"true\"></span><dt>변경된 납기일/공사기간</dt><dd>2026.07.20 ~ 2027.08.30</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경내용(메모)</dt><dd>품목 1종이 제외되어 계약금액을 수정하여 변경계약 하였습니다.</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 계약서</dt><dd>이미 등록된 파일명.PDF</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 시 참고서류</dt><dd>이미 등록된 파일명.PDF</dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMContractStatus/ctChangeFormModal.html": "<div class=\"modal-backdrop\" id=\"ctChangeFormModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ctChangeFormTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"ctChangeFormTitle\">계약 변경 처리하기</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <p class=\"modal-field-label\">변경 계약 처리(PMS로 계약정보 전송) 시 SRM과 PMS의 '계약정보'가 모두 업데이트되며, 계약변경일·변경내용(메모)·변경내역 상세보기 URL이 PMS로 추가 전송됩니다.</p>\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row\"><dt>계약변경일 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"date\" class=\"filter-date-input\"></dd></div>\n          <div class=\"srm-kv-row description-marker-container\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-9:1\" aria-hidden=\"true\"></span><dt>변경계약 사유 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><div class=\"form-choice-group\" role=\"radiogroup\"><label class=\"form-choice\"><input type=\"radio\" name=\"ctChangeReason\" checked value=\"amount\" data-ui-field=\"change\">'계약금액' 변경</label><label class=\"form-choice\"><input type=\"radio\" name=\"ctChangeReason\" value=\"period\" data-ui-field=\"change\">'납기일/공사기간' 변경</label></div></dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-9:2\" aria-hidden=\"true\"></span><dt>기존 계약금액</dt><dd>99,000,000원 (구천구백만원, VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-9:2’\" aria-hidden=\"true\"></span><dt>변경된 계약금액 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control\" placeholder=\"숫자로 입력해주세요.\"> 원 (VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-9:3\" aria-hidden=\"true\"></span><dt>기존 납기일/공사기간</dt><dd>2026.07.20 ~ 2027.07.30</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" data-description-ref=\"08-9:3’\" aria-hidden=\"true\"></span><dt>변경된 납기일/공사기간 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"date\" class=\"filter-date-input\"> ~ <input type=\"date\" class=\"filter-date-input\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>변경내용(메모) <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control grow\" placeholder=\"100자 이내로 등록해주세요.\" maxlength=\"100\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 계약서 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><div class=\"srm-file-list\"><div class=\"srm-file-item\"><span>이미 등록된 파일명.PDF</span><button type=\"button\" class=\"btn-row-del\">삭제</button></div></div><div class=\"form-lookup content-inner-gap-top\"><input type=\"text\" class=\"form-control\" readonly placeholder=\"파일을 첨부해주세요.\"><button type=\"button\" class=\"btn-secondary\">찾아보기</button></div></dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 시 참고서류</dt><dd><div class=\"form-lookup\"><input type=\"text\" class=\"form-control\" readonly placeholder=\"파일을 첨부해주세요.\"><button type=\"button\" class=\"btn-secondary\">찾아보기</button></div></dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\"><span class=\"description-target-marker\" data-description-ref=\"08-9:4\" aria-hidden=\"true\"></span><button type=\"button\" class=\"btn-critical-primary\" data-close-modal data-open-modal=\"ctChangeConfirmModal\">변경 계약 처리(PMS로 계약정보 전송)</button></span>\n        <button type=\"button\" class=\"btn-secondary\" data-close-modal>취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMContractStatus/ctConfirmSendModal.html": "<div class=\"modal-backdrop\" id=\"ctConfirmSendModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"ctConfirmSendTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"ctConfirmSendTitle\">확정 처리 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead\">'확정(수정 불가)'으로 처리된 내역(파일)을 계약정보에 업데이트합니다. 확정된 항목은 협력업체가 더 이상 수정할 수 없습니다.</p><p>확정 처리(계약정보로 전송)하시겠습니까?</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" data-description-ref=\"08-12:1’\" aria-hidden=\"true\"></span><button type=\"button\" class=\"btn-critical-primary\" data-close-modal>확정 처리(계약정보로 전송)</button></span><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMContractStatus/ctPartnerPickModal.html": "<div class=\"modal-backdrop\" id=\"ctPartnerPickModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ctPartnerPickTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-xl\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"ctPartnerPickTitle\">협력업체 선택</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <section class=\"filter-card\">\n          <form data-ui-scope=\"filter\">\n  <div class=\"filter-row hstack gap-12\">\n            <span class=\"filter-label w-130\">조회기간(신청일)</span>\n            <div class=\"date-range-wrap hstack gap-6\"><input type=\"date\" class=\"filter-date-input\"><span>~</span><input type=\"date\" class=\"filter-date-input\"></div>\n              <div class=\"quick-date-btns hstack gap-6\">\n                <button type=\"button\" class=\"btn-quick-date\" data-range=\"1d\">하루 전</button>\n                <button type=\"button\" class=\"btn-quick-date\" data-range=\"1w\">1주일</button>\n                <button type=\"button\" class=\"btn-quick-date active\" data-range=\"1m\">1개월</button>\n                <button type=\"button\" class=\"btn-quick-date\" data-range=\"3m\">3개월</button>\n                <button type=\"button\" class=\"btn-quick-date\" data-range=\"6m\">6개월</button>\n                <button type=\"button\" class=\"btn-quick-date\" data-range=\"1y\">1년</button>\n              </div>\n          </div>\n  <div class=\"filter-row hstack gap-12\">\n            <span class=\"filter-label w-130\">신용평가등급</span>\n            <select class=\"filter-select w-150\"><option>신용평가등급 선택</option></select>\n          </div>\n  <div class=\"filter-row hstack gap-12\">\n            <span class=\"filter-label w-130\">소싱 그룹</span>\n            <select class=\"filter-select w-140\"><option>대분류 선택</option></select>\n            <select class=\"filter-select w-140\"><option>중분류 선택</option></select>\n            <select class=\"filter-select w-140\"><option>소분류 선택</option></select>\n          </div>\n          <div class=\"filter-row hstack gap-12\">\n            <span class=\"filter-label w-130\">키워드 검색</span>\n            <span class=\"description-marker-anchor\"><span class=\"description-target-marker\" data-description-ref=\"08-5:1\" aria-hidden=\"true\"></span><select class=\"filter-select w-130\"><option>검색 구분</option></select></span>\n            <input type=\"text\" class=\"filter-text-input w-380\" placeholder=\"검색어를 입력하세요.\" aria-label=\"검색어\">\n          </div>\n            <div class=\"filter-action-row\">\n              <button type=\"button\" class=\"btn-filter-search\">검색</button>\n              <button type=\"button\" class=\"btn-filter-reset\">초기화</button>\n            </div>\n          </form>\n        </section>\n        <div class=\"table-card\">\n          <div class=\"table-header-action-row\">\n            <div class=\"table-total-count grid-page-summary\">1 / 153 (총 1,523개)</div>\n            <div class=\"table-actions\">\n              <select class=\"select-per-page\" title=\"페이지당 표시 건수\">\n                <option value=\"10\" selected>10개씩</option>\n                <option value=\"20\">20개씩</option>\n                <option value=\"50\">50개씩</option>\n              </select>\n            </div>\n          </div>\n          <div class=\"table-scroll-wrapper data-grid\" tabindex=\"0\" aria-label=\"협력업체 목록\" data-total-items=\"1523\" data-total-pages=\"153\">\n            <table class=\"data-table data-grid-table\" aria-label=\"협력업체 목록\">\n            <thead><tr><th>사업자 번호</th><th>업체명</th><th>담당자</th><th>핸드폰 번호</th><th>이메일</th><th>신청일</th><th class=\"w-70\">매핑</th></tr></thead>\n            <tbody>\n              <tr><td>123-45-67891</td><td class=\"text-left\">삼전디에스</td><td>한지훈</td><td>010-1234-5678</td><td>leehee43@naver.com</td><td>2026.06.10</td><td><button type=\"button\" class=\"btn-task-register\" data-close-modal>매핑</button></td></tr>\n              <tr><td>123-45-67891</td><td class=\"text-left\">넷퍼시</td><td>김미라</td><td>-</td><td>-</td><td>2026.06.10</td><td><button type=\"button\" class=\"btn-task-register\" data-close-modal>매핑</button></td></tr>\n            </tbody>\n          </table>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMContractStatus/screenDescriptionGuide.html": "<!-- 자동 생성 파일: 직접 수정하지 말고 docs/DESCRIPTION_MAP.json 수정 후 python3 tools/build_description_guides.py 실행 -->\n<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection1\">\n          <h3 id=\"descriptionSection1\">발주계약 현황(검색/조회)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 4</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">수의계약, 입찰 모두 ‘발주계약 현황’ 메뉴에서 만난다(종합 검색/조회 가능)\n\n계약요청의 전자결재가 완료(승인)되면, 본 ‘발주계약 현황’ 목록으로 이동\n- ‘계약번호’가 자동 발번됨\n- 진행상태 : ‘계약준비’</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">계약방법/낙찰자 선정방법별 검색 : 당연히 ‘수의계약’이 포함됨</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:3\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">켑코이에스의 ‘수주계약 기반의 발주’인지(수주계약의 매핑 여부로 판단), ‘일반 발주’(그 외)인지 제공</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:4\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">진행상태 정의 : 노란 부분 참조</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:5\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">검색 구분 : 계약 번호, 계약명</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-4:6\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">선택된 협력업체의 계약 내역만 조회\n협력업체 선택 팝업 호출(뒤 페이지)</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection2\">\n          <h3 id=\"descriptionSection2\">발주계약 현황(검색/조회) &gt; (협력업체 선택)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 5</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-5:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">7</span>\n              <pre class=\"description-source-text\">사업자 번호, 업체명, 담당자, 핸드폰 번호, 이메일</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMContractStatusDetail/screenDescriptionGuide.html": "<!-- 자동 생성 파일: 직접 수정하지 말고 docs/DESCRIPTION_MAP.json 수정 후 python3 tools/build_description_guides.py 실행 -->\n<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection1\">\n          <h3 id=\"descriptionSection1\">계약 정보</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 6</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-6:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">어두운 색으로 표시된 영역이 PMS와 연동되는 항목임 </pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection2\">\n          <h3 id=\"descriptionSection2\">계약 정보</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 7</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-7:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">기 등록된 정보 중 ‘근거 / 수의계약 사유’가 계약단계에서 명칭이 바뀜</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-7:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">계약금액을 기준으로 자동 산출해야 함</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-7:3\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">PMS는 ‘개월’로 입력하기 때문에 ‘개월’로 환산(*12)할 것\n\nPMS로 정보를 전송해야 함</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMContractStatusDetailBidPlan/screenDescriptionGuide.html": "<!-- 자동 생성 파일: 직접 수정하지 말고 docs/DESCRIPTION_MAP.json 수정 후 python3 tools/build_description_guides.py 실행 -->\n<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection1\">\n          <h3 id=\"descriptionSection1\">입찰계획 정보(입찰 시 화면)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 20</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-20:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">입찰 시 입찰계획 정보 제공 화면</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection2\">\n          <h3 id=\"descriptionSection2\">입찰계획 정보(입찰 시 화면)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 23</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-23:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">입찰신청이 진행되기 전(진행상태가 ‘공고대기’, ‘공고게시중’인 상태)에는 입찰계획 단계(입찰정보 수정 가능)로 되돌릴 수 있음</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection3\">\n          <h3 id=\"descriptionSection3\">입찰계획 정보(수의계약 시 화면)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 24</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-24:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">수의계약 시 입찰계획 정보 제공 화면</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-24:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">해당 공고 건이 ‘수의계약’의 경우 탭 메뉴명은 ‘수의계약 계획 정보’여야 함</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMContractStatusDetailDocs/screenDescriptionGuide.html": "<!-- 자동 생성 파일: 직접 수정하지 말고 docs/DESCRIPTION_MAP.json 수정 후 python3 tools/build_description_guides.py 실행 -->\n<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection1\">\n          <h3 id=\"descriptionSection1\">계약 정보</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 8</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-8:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">본 계약의 ‘계약금액’, ‘납기일/공사기간’에 변경이 발생하는 경우 활용하는 기능 (변경된 정보를 업데이트하고 변경 내용을 기록함)</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-8:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘계약 변경 처리하기’ 팝업 호출(뒤 페이지)</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-8:3\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">변경계약이 있는 경우 변경내역을 목록으로 제공</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection2\">\n          <h3 id=\"descriptionSection2\">계약 정보 &gt; (계약 변경 처리하기)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 9</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-9:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">변경 사유에 따라 아래의 입력 항목이 변경됨</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-9:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">‘계약금액’ 변경 시 입력항목</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-9:3\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">‘납기일/공사기간’ 변경 시 입력항목</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-9:4\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">7</span>\n              <pre class=\"description-source-text\">변경 계약 처리(PMS로 계약정보 전송) 시 PMS로 계약정보가 전송/업데이트\n\n변경된 내용(계약금액, 납기일/공사기간)을 SRM의 ‘계약정보’에 업데이트\n\n변경된 내용(계약금액, 납기일/공사기간)을 PMS의 ‘계약정보’에 업데이트\n\nPMS로 변경 내역 추가 전송(아래)\n- 계약변경일\n- 변경내용(메모)\n- 변경내역 정보 제공 팝업(계약 변경 내역 상세보기)을 호출하는 URL(뒤 페이지 팝업)</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSection3\">\n          <h3 id=\"descriptionSection3\">계약 정보 &gt; (계약 변경 내역 상세보기)</h3>\n          <p class=\"description-source-meta\">화면설계 08 · 슬라이드 10</p>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\" data-description-ref=\"08-10:1\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">8</span>\n              <pre class=\"description-source-text\">변경 사유에 따라 아래의 입력 항목이 노출됨</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-10:2\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">9</span>\n              <pre class=\"description-source-text\">‘계약금액’ 변경 시 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\" data-description-ref=\"08-10:3\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">10</span>\n              <pre class=\"description-source-text\">‘납기일/공사기간’ 변경 시 노출</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>"
});
